// Extraer y parsear los artículos hermanos del XML en el campo prompt
const items = [];

for (const item of $input.all()) {
  try {
    const prompt = item.json.prompt || '';
    const tareaAgente = item.json.tareaAgente || {};

    // Extraer la sección <articulos_hermanos>...</articulos_hermanos>
    const articulosMatch = prompt.match(/<articulos_hermanos>([\s\S]*?)<\/articulos_hermanos>/i);

    if (!articulosMatch) {
      console.log('No se encontró la sección articulos_hermanos');
      items.push({
        json: {
          articulos: [],
          tareaAgente: tareaAgente,
          error: 'No se encontró la sección articulos_hermanos'
        }
      });
      continue;
    }

    const articulosXML = articulosMatch[1];

    // Extraer cada artículo individual usando regex
    const articuloRegex = /<articulo_hermano>([\s\S]*?)<\/articulo_hermano>/gi;
    const articulos = [];

    let match;
    while ((match = articuloRegex.exec(articulosXML)) !== null) {
      const articuloXML = match[1];

      // Función helper para extraer contenido de una etiqueta
      const extractTag = (xml, tagName) => {
        const regex = new RegExp(`<${tagName}>([\\s\\S]*?)<\\/${tagName}>`, 'i');
        const match = xml.match(regex);
        return match ? match[1].trim() : '';
      };

      // Extraer cada campo del artículo
      const articulo = {
        titulo: extractTag(articuloXML, 'titulo'),
        url: extractTag(articuloXML, 'url'),
        nombre_sitio: extractTag(articuloXML, 'nombre_sitio'),
        cita_directa: extractTag(articuloXML, 'cita_directa'),
        dato_clave: extractTag(articuloXML, 'dato_clave')
      };

      // Solo agregar si tiene título y URL
      if (articulo.titulo && articulo.url) {
        articulos.push(articulo);
      }
    }

    // Preparar el output
    items.push({
      json: {
        articulos: articulos,
        tareaAgente: tareaAgente,
        totalArticulos: articulos.length
      }
    });

  } catch (error) {
    console.error('Error procesando item:', error);
    items.push({
      json: {
        articulos: [],
        tareaAgente: item.json.tareaAgente || {},
        error: error.message
      }
    });
  }
}

return items;

// Preparar la petición HTTP con autenticación Basic
const items = [];

for (const item of $input.all()) {
  const articulos = item.json.articulos || [];
  const tareaAgente = item.json.tareaAgente || {};

  // Limpiar espacios de la contraseña de aplicación
  const username = tareaAgente.WP_User_API || '';
  const password = (tareaAgente.WP_App_Password_API || '').replace(/\s/g, '');

  // Codificar credenciales en Base64 para Basic Auth
  const credentials = Buffer.from(`${username}:${password}`).toString('base64');

  items.push({
    json: {
      url: `${tareaAgente.Sitio_WordPress_URL_Destino}wp-json/network-recs/v1/update`,
      authorization: `Basic ${credentials}`,
      body: articulos,
      totalArticulos: articulos.length
    }
  });
}

return items;
